package com.skyreserve;
import com.skyreserve.model.*; import com.skyreserve.repo.*; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.context.annotation.Bean; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import java.time.LocalDate;
@SpringBootApplication public class SkyReserveApplication { public static void main(String[] a){SpringApplication.run(SkyReserveApplication.class,a);} @Bean BCryptPasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean CommandLineRunner seed(UserRepository u,FlightRepository f,BCryptPasswordEncoder e){return a->{if(u.findByEmail("admin@skyreserve.com").isEmpty()){User x=new User();x.setName("SkyReserve Admin");x.setEmail("admin@skyreserve.com");x.setPassword(e.encode("admin123"));x.setRole("ADMIN");u.save(x);} if(f.count()==0){f.save(new Flight("AI101","Air India","Mumbai","Delhi",LocalDate.now().plusDays(1),"09:30",4999,6,6));f.save(new Flight("6E202","IndiGo","Mumbai","Bengaluru",LocalDate.now().plusDays(1),"13:15",3999,6,6));f.save(new Flight("UK303","Vistara","Delhi","Mumbai",LocalDate.now().plusDays(2),"18:45",5299,6,6));f.save(new Flight("SG404","SpiceJet","Mumbai","Goa",LocalDate.now().plusDays(3),"11:00",2999,6,6));}};}}
